import React, { useState, useEffect } from 'react';
import { Github, Linkedin, Mail, Phone, ExternalLink, Briefcase, Code, Database, Cloud, Brain, ChevronDown, Download, Menu, X, ArrowRight, Sparkles, Zap, Target } from 'lucide-react';

const Portfolio = () => {
  const [scrollY, setScrollY] = useState(0);
  const [activeSection, setActiveSection] = useState('hero');
  const [menuOpen, setMenuOpen] = useState(false);
  const [typedText, setTypedText] = useState('');
  const fullText = "AI & Machine Learning Engineer";

  useEffect(() => {
    const handleScroll = () => {
      setScrollY(window.scrollY);
      const sections = ['hero', 'about', 'experience', 'projects', 'skills', 'contact'];
      const current = sections.find(section => {
        const element = document.getElementById(section);
        if (element) {
          const rect = element.getBoundingClientRect();
          return rect.top <= 100 && rect.bottom >= 100;
        }
        return false;
      });
      if (current) setActiveSection(current);
    };

    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  useEffect(() => {
    if (typedText.length < fullText.length) {
      const timeout = setTimeout(() => {
        setTypedText(fullText.slice(0, typedText.length + 1));
      }, 100);
      return () => clearTimeout(timeout);
    }
  }, [typedText]);

  const projects = [
    {
      title: "Deep Farming",
      subtitle: "Crop Disease Surveillance",
      description: "Smart farming solution using CNN models for crop disease detection. Achieved 95%+ accuracy and deployed via Flask for real-time predictions.",
      tags: ["Python", "TensorFlow", "CNN", "Flask"],
      icon: "🌱",
      gradient: "from-green-500 to-emerald-600"
    },
    {
      title: "Intelligent SQL-Gen",
      subtitle: "NLP to SQL via RAG",
      description: "Engineered automated pipelines using Azure OpenAI and LangChain to perform semantic schema-linking, eliminating hallucinations in SQL generation.",
      tags: ["Azure OpenAI", "LangChain", "FAISS", "Streamlit"],
      icon: "💬",
      gradient: "from-blue-500 to-cyan-600"
    },
    {
      title: "Healthcare Guidance Navigator",
      subtitle: "Agentic AI Clinical Support",
      description: "RAG-based healthcare chatbot providing document-specific clinical guidance and real-time medical insights using LangGraph and ChromaDB.",
      tags: ["Agentic AI", "ChromaDB", "LangGraph", "OpenAI"],
      icon: "🏥",
      gradient: "from-pink-500 to-rose-600"
    }
  ];

  return (
    <div className="bg-black text-white min-h-screen relative selection:bg-purple-500/30">
      
      {/* --- BACKGROUND ELEMENTS --- */}
      {/* 1. Animated Grid Pattern */}
      <div className="fixed inset-0 z-0 opacity-20 pointer-events-none" 
           style={{ backgroundImage: 'linear-gradient(#1e1e1e 1px, transparent 1px), linear-gradient(90deg, #1e1e1e 1px, transparent 1px)', backgroundSize: '40px 40px' }}>
      </div>
      
      {/* 2. Floating Ambient Glows */}
      <div className="fixed top-[-10%] left-[-10%] w-[50%] h-[50%] bg-purple-900/20 blur-[120px] rounded-full animate-pulse z-0"></div>
      <div className="fixed bottom-[-10%] right-[-10%] w-[50%] h-[50%] bg-blue-900/20 blur-[120px] rounded-full animate-pulse z-0" style={{ animationDelay: '2s' }}></div>

      {/* Navigation */}
      <nav className="fixed top-0 w-full z-50 backdrop-blur-xl bg-black/50 border-b border-white/10">
        <div className="max-w-7xl mx-auto px-6 py-4 flex justify-between items-center">
          <div className="text-2xl font-bold bg-gradient-to-r from-purple-400 to-blue-400 bg-clip-text text-transparent">
            ROHIT HARNE
          </div>
          <div className="hidden md:flex gap-8 items-center font-medium">
            {['About', 'Experience', 'Projects', 'Skills'].map((item) => (
              <a key={item} href={`#${item.toLowerCase()}`} className="hover:text-purple-400 transition-colors uppercase tracking-widest text-xs">
                {item}
              </a>
            ))}
            <a href="mailto:rohitharne21@gmail.com" className="px-5 py-2 bg-white/10 rounded-full hover:bg-white/20 transition-all text-xs uppercase tracking-tighter">
              Contact Me
            </a>
          </div>
          <button className="md:hidden" onClick={() => setMenuOpen(!menuOpen)}>{menuOpen ? <X /> : <Menu />}</button>
        </div>
      </nav>

      {/* Hero Section */}
      <section id="hero" className="relative min-h-screen flex items-center justify-center px-6 pt-20 z-10">
        <div className="max-w-7xl mx-auto w-full">
          <div className="flex flex-col md:flex-row items-center justify-between gap-12">
            
            <div className="flex-1 text-center md:text-left">
              <span className="inline-block py-1 px-3 rounded-full bg-purple-500/10 border border-purple-500/20 text-purple-400 text-xs font-bold mb-6 tracking-widest uppercase">
