              </span>
              <h1 className="text-6xl md:text-8xl font-black mb-4 tracking-tighter">
                ROHIT <span className="bg-gradient-to-r from-purple-400 via-pink-400 to-blue-400 bg-clip-text text-transparent">HARNE</span>
              </h1>
              <div className="h-10 mb-6">
                <p className="text-xl md:text-3xl font-light text-gray-400">
                  {typedText}<span className="animate-pulse text-purple-500">_</span>
                </p>
              </div>
              <p className="text-gray-400 max-w-lg mb-10 leading-relaxed text-lg">
