              <div className="flex gap-4 justify-center md:justify-start flex-wrap">
                <a href="#projects" className="group px-8 py-4 bg-white text-black rounded-full hover:bg-purple-500 hover:text-white transition-all font-bold flex items-center gap-2">
                  View Projects <ArrowRight className="w-4 h-4" />
                </a>
                {/* UPDATED RESUME LINK */}
                <a href="/Rohit_Harne.Resume--.pdf" download className="px-8 py-4 border border-white/20 rounded-full hover:bg-white/10 transition-all font-bold flex items-center gap-2">
