            <div className="flex-shrink-0 relative">
              <div className="absolute inset-0 bg-gradient-to-tr from-purple-600 to-blue-600 rounded-full blur-3xl opacity-30 animate-pulse"></div>
              <img 
                src="/profile.jpg" 
                alt="Rohit Harne" 
                className="relative w-72 h-72 md:w-96 md:h-96 rounded-3xl object-cover border border-white/10 grayscale hover:grayscale-0 transition-all duration-700 shadow-2xl"
              />
              <div className="absolute -bottom-4 -right-4 p-6 bg-black/80 backdrop-blur-md border border-white/10 rounded-2xl shadow-xl">
