                <h3 className="text-2xl font-bold mb-2">{project.title}</h3>
                <p className="text-gray-400 text-sm mb-6 line-clamp-3">{project.description}</p>
                <div className="flex flex-wrap gap-2 mb-8">
                  {project.tags.map(tag => (
                    <span key={tag} className="text-[10px] uppercase font-bold tracking-widest px-3 py-1 bg-white/5 rounded-md border border-white/5">{tag}</span>
                  ))}
                </div>
                <button className="flex items-center gap-2 text-sm font-bold text-purple-400 group-hover:text-purple-300">
                  Case Study <ExternalLink className="w-4 h-4" />
                </button>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* Footer */}
      <footer className="py-12 px-6 border-t border-white/5 relative z-10">
        <div className="max-w-7xl mx-auto flex flex-col md:flex-row justify-between items-center gap-8">
          <p className="text-gray-500 text-sm">© 2024 Rohit Harne • AI/ML Engineer</p>
          <div className="flex gap-6">
            <a href="https://linkedin.com" className="text-gray-400 hover:text-white transition-colors"><Linkedin className="w-5 h-5" /></a>
            <a href="https://github.com" className="text-gray-400 hover:text-white transition-colors"><Github className="w-5 h-5" /></a>
            <a href="mailto:rohitharne21@gmail.com" className="text-gray-400 hover:text-white transition-colors"><Mail className="w-5 h-5" /></a>
          </div>
        </div>
